-- Report 2.5: 0o17, 0O17, 0xff and 0XFf; a literal of 1000 digits at Integer; a floating literal is the exact n/d at a user
-- Fractional type; 2.4: a qualified operator has the fixity of the operator it names (1 Prelude.+ 2 * 3 is 7).
module Main (main) where

newtype L = L String
instance Eq L where
  L a == L b = a == b
instance Show L where
  show (L s) = s
instance Num L where
  fromInteger i = L (show i)
  _ + _ = L "+"
  _ * _ = L "*"
  negate _ = L "-"
  abs _ = L "abs"
  signum _ = L "signum"
instance Fractional L where
  fromRational r = L (show r)
  _ / _ = L "/"

